// Strip HTML, drop quoted reply chains, collapse whitespace, cap length.
const item = $input.first().json;

const subject = item.subject || item.headers?.subject || '(no subject)';
const from    = item.from    || item.headers?.from    || 'unknown sender';
const date    = item.date    || item.headers?.date    || new Date().toISOString();
const labels  = item.labels || item.labelIds || [];

let body = item.text || item.textPlain || item.body || item.snippet || '';

if (/<[a-z][\s\S]*>/i.test(body)) {
  body = body
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<\/?[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

body = body.replace(/On .+ wrote:\s*[\s\S]*$/i, '');
body = body.replace(/\s+/g, ' ').trim().slice(0, 8000);

return [{ json: { messageId: item.id, threadId: item.threadId, subject, from, date, labels, body } }];

