// Parse Gemini JSON, validate, fall back to safe defaults.
const out = $input.first().json;
const prepared = $('Clean Body').first().json;

let parsed = null;
try {
  const text = out?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (text) parsed = JSON.parse(text);
} catch (e) { parsed = null; }

const validPriorities = ['Low', 'Medium', 'High'];
const validCategories = ['Work', 'Finance', 'Personal', 'Notification', 'Other'];

const safe = parsed || {
  summary: (prepared.body || '').slice(0, 200) || '(no summary available)',
  priority: 'Low',
  category: 'Other',
  action_items: [],
  deadline: null
};

return [{ json: {
  messageId: prepared.messageId,
  subject:   prepared.subject,
  from:      prepared.from,
  date:      prepared.date,
  summary:   String(safe.summary || '').slice(0, 1000),
  priority:  validPriorities.includes(safe.priority) ? safe.priority : 'Low',
  category:  validCategories.includes(safe.category) ? safe.category : 'Other',
  action_items: Array.isArray(safe.action_items) ? safe.action_items.slice(0, 10).map(String) : [],
  deadline: safe.deadline ? String(safe.deadline).slice(0, 200) : null
}}];

// Build Slack Block Kit message: header (priority+category), subject, context, summary, action items, deadline, footer.
const d = $input.first().json;

const priorityEmoji = d.priority === 'High' ? '🔴' : d.priority === 'Medium' ? '🟡' : '🟢';
const priorityColor = d.priority === 'High' ? '#e01e5a' : d.priority === 'Medium' ? '#ecb22e' : '#2eb67d';
const categoryEmoji = ({ Work: '💼', Finance: '💰', Personal: '👤', Notification: '🔔', Other: '📨' })[d.category] || '📨';

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `${priorityEmoji} ${d.priority.toUpperCase()} — ${categoryEmoji} ${d.category}`, emoji: false } },
  { type: 'section', text: { type: 'mrkdwn', text: `*${(d.subject || '(no subject)').slice(0, 200)}*` } },
  { type: 'context', elements: [
    { type: 'mrkdwn', text: `*From:* ${d.from || 'unknown'}` },
    { type: 'mrkdwn', text: `*Date:* ${d.date || 'unknown'}` }
  ]},
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: `*Summary*\n${d.summary || '_no summary_'}` } }
];

if (Array.isArray(d.action_items) && d.action_items.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Action items*\n' + d.action_items.map(a => `• ${a}`).join('\n') } });
} else {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Action items*\n_None_' } });
}

if (d.deadline) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Deadline:* ⏰ ${d.deadline}` } });
} else {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Deadline:* _None_' } });
}

blocks.push({ type: 'divider' });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `messageId: \`${d.messageId}\`` }] });

return [{ json: {
  channel: 'REPLACE_WITH_SLACK_CHANNEL_ID',
  text: `📧 ${d.subject || 'New email'} — ${priorityEmoji} ${d.priority} — ${categoryEmoji} ${d.category}`,
  blocks: JSON.stringify(blocks),
  attachments: JSON.stringify([{ color: priorityColor }]),
  messageId: d.messageId,
  subject: d.subject,
  from: d.from,
  priority: d.priority,
  category: d.category
}}];
